interface User { id: number; nome: string; senha: string; }

type CriarUser = Omit<User, "id">;        // { nome, senha }
type AtualizarUser = Partial<CriarUser>;   // { nome?: string; senha?: string }
type PublicUser = Pick<User, "id" | "nome">;

function formatar(v: string | number) {
  return typeof v === "string" ? v.toUpperCase() : v.toFixed(2);
}
